use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_valid_char(c: char) -> bool {
    c == 'H' || c == 'D'
}

spec fn is_valid_input(input: Seq<char>) -> bool {
    input.len() >= 3 &&
    is_valid_char(input[0]) &&
    input[1] == ' ' &&
    is_valid_char(input[2]) &&
    (input.len() > 3 ==> input[3] == '\n')
}

fn solve(input: Vec<char>) -> (result: Vec<char>)
    requires
        is_valid_input(input@),
    ensures
        result@.len() == 2,
        result@[1] == '\n',
        (input@[0] == input@[2]) ==> result@[0] == 'H',
        (input@[0] != input@[2]) ==> result@[0] == 'D',
{
    // The input satisfies the precondition, so we can safely access indices 0, 1, 2
    let first = input[0];
    let third = input[2];
    
    let output_char = if first == third {
        'H'
    } else {
        'D'
    };
    
    // Create the result vector with exactly 2 characters
    let mut result_vec = Vec::new();
    result_vec.push(output_char);
    result_vec.push('\n');
    
    result_vec
}

}
